Translate("ruRU", "first-mate-fitzsimmons", {
	title = "Старший помощник Фицсиммонс",
	subtitle = "Последний уцелевший из Третьего флота",
	found = "Таверна «Большая вода», Гавань Менетилов",
	hint = [=[Угостите выпивкой моряка, который топит свои воспоминания в таверне «Большая вода».]=],
	allegiance = "Кул Тирас (в прошлом)",
	aliases = { "Фицсиммонс" },
	sections = {
		{
			title = "Обзор",
			text = [=[Фицсиммонс был старшим помощником на линейном корабле {i}Владычица Волн{/i} из {link:third-fleet}Третьего флота{/link} {link:kul-tiras}Кул Тираса{/link}. В последнем походе флота на него напали красные драконы, оседланные {link:orcs}орк{/link}ами, и сожгли его у берегов Болотины. Выжил он один. Теперь он проводит дни в таверне «Большая вода», пропахший кислым и вечно жаждущий, а ночами видит во сне своих утонувших братьев.]=],
		},
		{
			title = "Значение",
			text = [=[Фицсиммонс — живая память Обреченного флота. Только он знает, что на борту одного из его кораблей было спрятано нечто ужасное и что сила этой вещи не дает мертвым упокоиться.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он рассказывает историю Третьего флота всякому, кто купит ему медовухи.
• Он просит освободить его проклятых братьев.
• Он посылает искателей к призраку капитана {link:captain-halyndor}Халиндор{/link}а за ключом от корабельного сундука.
• Он указывает путь к духу болот, Зеленому Стражу, и предостерегает искателя, чтобы тот не ходил.]=],
		},
	},
	chapters = {
		{
			title = "Обреченный флот",
			hint = "Развяжите старому моряку язык кружкой медовухи.",
			text = [=[Со свежей выпивкой в руке Фицсиммонс рассказывает все прямо. Флот вышел в море; прилетели драконы; корабли сгорели и пошли ко дну. Он не знает, почему остался жив. Он проклинает своего капитана за то, что тот привел их к гибели, и пьет за братьев в их водяных могилах.]=],
		},
		{
			title = "Проклятое око",
			hint = "Откройте сундук корабля «Неустрашимый».",
			text = [=[{link:captain-halyndor}Капитан Халиндор{/link} держал эту вещь под замком в своем сундуке на борту корабля {i}Неустрашимый{/i}. Когда сундук открыли, в нем лежала почерневшая сфера, пульсировавшая болезненным светом: Око Палета, оскверненное скорбью, свидетелем которой оно стало. Фицсиммонс не пожелал к нему прикасаться. Он отослал его жрецу {link:glorin-steelbrow}Глорин{/link}у Стальной Брови.]=],
		},
	},
	mentions = {
		{ text = "{link:third-fleet}Третий флот{/link}" },
		{ text = "Проклятая команда" },
		{ text = "Снятие проклятия" },
		{ text = "{link:rethiel-the-greenwarden}Зеленый Страж{/link}" },
	},
	bonds = {
		{ id = "captain-halyndor", name = "Капитан Халиндор", note = "его прежний капитан, которого он винит" },
		{ id = "glorin-steelbrow", name = "Глорин Стальная Бровь", note = "получил Око" },
		{ id = "rethiel-the-greenwarden", name = "Ретиэль Зеленый Страж", note = "дух, о котором он предостерегает" },
	},
})

Translate("ruRU", "glorin-steelbrow", {
	title = "Глорин Стальная Бровь",
	subtitle = "Жрец Менетила",
	found = "Таверна «Большая вода», Гавань Менетилов",
	hint = "Найдите дворфа-жреца, который знает тайны затонувшего флота.",
	allegiance = "Королевство Стальгорн · Церковь Света",
