})

Translate("ruRU", "longbraid-the-grim", {
	title = "Длиннокос Мрачный",
	subtitle = "Командир полка Дун Модра",
	found = "Лагерь у стен Дун Модра",
	hint = [=[Разыщите дворфа-командира, который держит лагерь у стен павшего Дун Модра.]=],
	allegiance = "Королевство Стальгорн",
	aliases = { "Длиннокос" },
	sections = {
		{
			title = "Обзор",
			text = [=[Длиннокос Мрачный вел полк {link:ironforge}Стальгорн{/link}а, охранявший {link:dun-modr}Дун Модр{/link} и {link:thandol-span}Мост Тандола{/link}. Он потерял и то, и другое. {link:dark-iron-dwarves}Дворфы Черного Железа{/link} взорвали западный мост из засады, и с мостом погиб его брат. Прежде чем полк успел оправиться, они обрушились на город. Длиннокос протрубил в рог отступление, и теперь он держит маленький лагерь у стен с теми немногими, кто выжил.]=],
		},
		{
			title = "Значение",
			text = [=[Длиннокос — скорбь и упрямство Каз Модана в одном {link:dwarves}дворф{/link}е. У него нет ни резерва, ни лишних союзников, ни города, и все же он не ушел с дороги на север.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он протрубил отступление, когда пал {link:dun-modr}Дун Модр{/link}, и спас то, что осталось от его полка.
• Он отправил на юг, в Менетил, всадника с раненым солдатом по имени {link:harlo-barnaby}Харло Барнаби{/link}.
• Он охотится за чернокнижником, который возглавляет {link:dwarves}дворф{/link}ов Черного Железа в Болотине.
• Он послал к восточному мосту разведчика, Старину Растлока, и разведчик не вернулся.]=],
		},
	},
	chapters = {
		{
			title = "Падение Дун Модра",
			hint = "Принесите весть от раненого солдата из Менетила.",
			text = [=[Длиннокос услышал, что юный {link:harlo-barnaby}Харло{/link} жив, и на миг эта весть подарила ему надежду. Затем он прямо рассказал остальное. {link:dun-modr}Дун Модр{/link} потерян. От полка, что удерживал его, осталась лишь тень.]=],
		},
		{
			title = "Мрачное дело",
			hint = [=[Выследите чернокнижника, который возглавляет дворфов Черного Железа.]=],
			text = [=[Дворфов Черного Железа в Болотине вел {link:balgaras-the-foul}Балгарас Гнусный{/link}, чернокнижник, который посылал на смерть других, а сам держался вне досягаемости. Когда его ухо положили перед командиром, Длиннокос не испытал радости. Мертвые не вернутся. Но живые, быть может, смогут спать, а остальных {link:dwarves}дворф{/link}ов Черного Железа предстоит изгнать, пока не явился новый господин.]=],
		},
	},
	mentions = {
		{ text = "Падение {link:dun-modr}Дун Модр{/link}а" },
		{ text = "Мрачное дело" },
		{ text = "Глубокая ярость, его брат отомщен" },
		{ text = "В поисках отряда землекопов" },
	},
	bonds = {
		{ id = "motley-garmason", name = "Мотли Гармасон", note = "честь обязывает его оставаться рядом с командиром" },
		{ id = "rhag-garmason", name = "Раг Гармасон", note = "его офицер" },
		{ id = "harlo-barnaby", name = "Харло Барнаби", note = "солдат, которого он отослал в безопасное место" },
		{ id = "balgaras-the-foul", name = "Балгарас Гнусный", note = "враг" },
		{ id = "kam-deepfury", name = "Кам Гнев Глубин", note = "задумал гибель его брата" },
	},
})

