Translate("ruRU", "chieftain-nek-rosh", {
	title = "Вождь Нек'рош",
	subtitle = "Вождь клана Драконьей Пасти",
	found = "Лагерь Злого Клыка",
	hint = [=[Сразитесь с вождем, который ведет клан Драконьей Пасти из лагеря в восточных холмах.]=],
	allegiance = "Клан Драконьей Пасти",
	aliases = { "Нек'рош" },
	sections = {
		{
			title = "Обзор",
			text = [=[Нек'рош — вождь {link:dragonmaw-clan}клана Драконьей Пасти{/link} в Болотине. Он сын {link:orcs}орк{/link}а Некроса, который возглавлял клан в те годы, когда тот держал в плену красных драконов. Некрос подчинял драконов своей воле могучей магией. Когда магия иссякла, драконы обратились против своих хозяев, и Некрос был убит. Его сын поклялся отомстить драконам, которые его погубили.]=],
		},
		{
			title = "Значение",
			text = [=[Под началом вождя Нек'роша разбитый клан снова стал войском. {link:orcs}Орки{/link} Драконьей Пасти ворвались в {link:dun-algaz}Дун Альгаз{/link}, построили осадные машины и обратили взор на {link:menethil-harbor}Гавань Менетилов{/link}.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он собрал рассеянных {link:orcs}орк{/link}ов Драконьей Пасти в Лагере Злого Клыка.
• Он бросил своих воинов в {link:dun-algaz}Дун Альгаз{/link} и перерезал дорогу между Менетилом и {link:loch-modan}Лок Модан{/link}ом.
• Он построил катапульты, чтобы осадить {link:menethil-harbor}Гавань Менетилов{/link}.]=],
		},
		{
			title = "Чего нет в летописях",
			text = [=[Летописи Второй войны рассказывают об {link:orcs}орк{/link}ах Драконьей Пасти, что держали Королеву драконов в {link:grim-batol}Грим Батол{/link}е. Какую роль в те годы играл сам Нек'рош, они не говорят.]=],
		},
	},
	chapters = {
		{
			title = "Сын орка Некроса",
			hint = [=[Отнесите боевые знамена клана Драконьей Пасти капитану в Крепость Менетил.]=],
			text = [=[Когда знамена положили перед ним, капитан {link:captain-stoutfist}Крепкий Кулак{/link} рассказал, что {link:dwarves}дворф{/link}ы знают о своем враге. {link:dragonmaw-clan}Клан Драконьей Пасти{/link} уже не тот, каким был, когда летал на драконах. Его вождь — сын {link:orcs}орк{/link}а, который некогда поработил красных драконов, и он не забыл, как погиб его отец.]=],
		},
		{
			title = "Разбить вождя Нек'роша",
			hint = "Сожгите катапульты и сразите вождя.",
			text = [=[Сперва сгорели катапульты, и Менетилу они больше не грозили. Затем Нек'рош пал в собственном лагере. {link:captain-stoutfist}Крепкий Кулак{/link} счел это тяжким ударом, от которого клан, быть может, уже не оправится.]=],
		},
	},
	mentions = {
		{ text = "Боевые знамена" },
		{ text = "Замысел вождя Нек'роша" },
		{ text = "Разбить вождя Нек'роша" },
	},
	bonds = {
		{ id = "captain-stoutfist", name = "Капитан Крепкий Кулак", note = "враг" },
		{ id = "ma-ruk-wyrmscale", name = "Ма'рук Змеиная Чешуя", note = "его полководец в Дун Альгазе" },
		{ id = "alexstrasza", name = "Алекстраза", note = "королева драконов, которых поработил его отец" },
	},
})

Translate("ruRU", "ma-ruk-wyrmscale", {
	title = "Ма'рук Змеиная Чешуя",
	subtitle = "Полководец клана Драконьей Пасти",
	found = "Дун Альгаз",
	hint = [=[Сразитесь с полководцем клана Драконьей Пасти, который удерживает перевал Дун Альгаз.]=],
	allegiance = "Клан Драконьей Пасти",
	aliases = { "Ма'рук" },
	sections = {
		{
			title = "Обзор",
			text = [=[Ма'рук Змеиная Чешуя — полководец {link:dragonmaw-clan}клана Драконьей Пасти{/link}. Он ведет {link:orcs}орк{/link}ов, спустившихся в перевал {link:dun-algaz}Дун Альгаз{/link}, где они устраивают засады на каждого путника между {link:loch-modan}Лок Модан{/link}ом и Болотиной. Пока он удерживает перевал, никакие подкрепления не дойдут до Гавани Менетилов по суше.]=],
