		},
	},
	bonds = {
		{ id = "chieftain-nek-rosh", name = "Вождь Нек'рош", note = "его вождь" },
	},
})

Translate("ruRU", "dragonmaw-clan", {
	title = "Клан Драконьей Пасти",
	aliases = { "клан Драконьей Пасти", "орки Драконьей Пасти" },
	sections = {
		{
			title = "Обзор",
			text = [=[Клан Драконьей Пасти — клан {link:orcs}орков{/link} старой {link:horde}Орды{/link}. Во {link:second-war}Вторую войну{/link} он сделал то, чего не смог ни один другой клан: превратил красных драконов в своих слуг. В своей твердыне {link:grim-batol}Грим Батол{/link} орки держали в плену Королеву драконов {link:alexstrasza}Алекстразу{/link} силой артефакта, который выковал {link:deathwing}Смертокрыл{/link}, и растили ее детенышей как боевых скакунов. Красные драконы, оседланные орками Драконьей Пасти, жгли корабли {link:alliance}Альянс{/link}а в море.]=],
		},
		{
			title = "Падение",
			text = [=[Магия, сковывавшая драконов, иссякла. Красные драконы обратились против клана и преследовали его без пощады. Некрос, возглавлявший клан Драконьей Пасти, был убит, а сам клан почти уничтожен. Немногие уцелевшие бежали из {link:grim-batol}Грим Батол{/link}а и укрылись в горах к востоку от дороги через Болотину.]=],
		},
		{
			title = "В наши дни",
			text = [=[Клан Драконьей Пасти снова набрал силу под началом вождя {link:chieftain-nek-rosh}Нек'рош{/link}а, сына Некроса. Из Лагеря Злого Клыка и из тайного Приюта Драконьей Пасти {link:orcs}орк{/link}и наносят удары на запад, и они захватили перевал {link:dun-algaz}Дун Альгаз{/link}. Они строят катапульты, собирают оружие и, как шепчут, все еще грезят о драконах. {link:dwarves}Дворфы{/link} Менетила называют их свирепыми, но знают, что клан без драконов — меньшая угроза, чем клан, некогда затмевавший небо.]=],
		},
	},
})

Translate("ruRU", "third-fleet", {
	title = "Третий флот",
	aliases = { "Обреченный флот" },
	sections = {
		{
			title = "Обзор",
			text = [=[Третий флот {link:kul-tiras}Кул Тираса{/link} вышел в море во {link:second-war}Вторую войну{/link}, последнюю великую войну против Орды. Его корабли шли от берегов {link:lordaeron}Лордерон{/link}а, и ради защиты к нему примкнуло по меньшей мере одно чужое судно: {i}Летящая скопа{/i}, которое везло груз светокованого железа. У побережья Болотины на флот напали {link:orcs}орк{/link}и верхом на красных драконах. Корабли сгорели и затонули, и остовы их до сих пор лежат вдоль северо-западного берега, в месте, которое зовется {link:the-lost-fleet}Погибший Флот{/link}.]=],
		},
		{
			title = "Проклятие",
			text = [=[На борту корабля {i}Неустрашимый{/i} было спрятано проклятое Око Палета, запертое в капитанском сундуке. Такие Очи создавали человеческие жрецы, чтобы те сияли священным светом, но это Око видело слишком много скорби. Его сила удерживает утонувшие команды в их гниющих корпусах. Из всего флота жив лишь один человек, старший помощник {link:first-mate-fitzsimmons}Фицсиммонс{/link}, и он пьет в Менетиле, чтобы не видеть их во сне.]=],
		},
		{
			title = "Груз",
			text = [=[{link:murlocs}Мурлоки{/link} побережья обшарили {i}Летящую скопу{/i}. Ее слитки светокованого железа ценят те, кто сражается с нежитью. Ночная эльфийка из {link:teldrassil}Тельдрассил{/link}а, {link:sylessa-duskwhisper}Силесса Сумеречный Шепот{/link}, говорит, что корабль вез также Норд'ел, цветок с горы Хиджал.]=],
		},
	},
})

Translate("ruRU", "goaz-stone", {
	title = "Камень Гоаз",
	aliases = { "Камень Гоаз" },
	sections = {
		{
			title = "Обзор",
			text = [=[Камень Гоаз — большая плита, которую геолог {link:prospector-whelgar}Вельгар{/link} извлек из земли на своих раскопках в Болотине перед самым нашествием ящеров. Она покрыта письменами титанов. Когда ее нашли, она была расколота в четырех местах, а пропавшие куски носили имена Адос, Модр, Голм и Неру. Даже неполная, плита говорила о божественном замысле и обреченном пророчестве.]=],
		},
		{
			title = "Прочтение",
			text = [=[Когда четыре обломка вернули на место, {link:prospector-whelgar}Вельгар{/link} начал медленный труд перевода. Первые новые слова, которые он прочел, говорили о Древних богах, закованных под землей. {link:explorers-league}Лига исследователей{/link} находила резные письмена титанов и прежде, но редко такие, что столь прямо говорят о лежащем внизу.]=],
		},
		{
			title = "Наши дни",
			text = [=[{link:prospector-whelgar}Вельгар{/link} не закончил чтения. Над его раскопками, в холмах, с гор начал спускаться туман, и создания титанов снова ходят по земле. Связаны ли камень и пробуждение нагорья, Лига пока не знает.]=],
		},
	},
})
